function renderMessage(m){log.querySelector('.s17-agent-welcome')?.remove();const wrap=document.createElement('article');wrap.className='s17-agent-message';wrap.dataset.role=m.role;const label=document.createElement('small');label.className='s17-message-origin';label.textContent=m.role==='user'?'你':m.origin||'井见 · 本地导览';const content=document.createElement('div');content.className='s17-message-content';richText(content,m.content);wrap.append(label,content);if(m.actions?.length){const row=document.createElement('div');row.className='s17-agent-actions';actionLinks(row,m.actions);wrap.append(row);}if(m.role==='assistant'){const copy=document.createElement('button');copy.type='button';copy.className='s17-message-copy';copy.innerHTML=icon('copy')+'<span>复制</span>';copy.onclick=async()=>{try{await navigator.clipboard.writeText(m.content);toast('回复已复制');}catch{toast('可选中文字，使用系统复制');}};wrap.append(copy);}log.append(wrap);log.scrollTop=log.scrollHeight;}
function updateBubble(){const m=[...history].reverse().find(m=>m.role==='assistant');lastReply=m?.content??'';$('s17-agent-excerpt').textContent=busy?'正在想一想，稍等一下…':lastReply||'你好，我是井见。想了解当前案例，还是找一个新的知识点？';actionLinks($('s17-agent-bubble-actions'),busy?[]:m?.actions??[],1);$('s17-agent-full').hidden=busy||!history.length;$('s17-agent-reply').hidden=root.dataset.open!=='true';}
function renderConversation(){history=store.current().messages;log.replaceChildren();if(!history.length)welcome();else history.forEach(renderMessage);updateBubble();updateContext();}
function storageNotice(){const persistent=store.snapshot().status==='persistent';$('s17-agent-storage').textContent=persistent?'已保存在本机浏览器':'本页无法持久保存，离开后不会保留本次对话';root.dataset.storage=persistent?'persistent':'memory';}
function resetDraft(){g.S17Media?.cancelRecording();g.S17Media?.clear();g.speechSynthesis?.cancel();root.dataset.speaking='false';$('s17-agent-input').value='';$('s17-agent-input').style.height='';syncComposer();}
function renderSessions(){const host=$('s17-agent-sessions');host.replaceChildren();for(const s of store.list()){const row=document.createElement('div');row.className='s17-session-row';row.dataset.sessionId=s.id;const button=document.createElement('button');button.type='button';button.className='s17-session-open';const title=document.createElement('strong'),date=document.createElement('span');title.textContent=s.title;date.textContent=new Date(s.updatedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+' · '+s.count+'条消息';button.append(title,date);button.onclick=()=>{stopRequest();resetDraft();store.activate(s.id);renderConversation();showHistory(false);};const remove=document.createElement('button');remove.type='button';remove.className='s17-session-delete';remove.setAttribute('aria-label','删除对话：'+s.title);remove.innerHTML=icon('trash');remove.title='删除这段对话';remove.onclick=()=>{if(store.current().id===s.id){stopRequest();resetDraft();}store.remove(s.id);renderConversation();renderSessions();storageNotice();};row.append(button,remove);host.append(row);}if(!host.children.length){const empty=document.createElement('p');empty.textContent='还没有历史对话。发送一条消息后会自动保存。';host.append(empty);}}
function append(role,text,actions=[],origin='井见 · 本地导览'){const m=store.append({role,content:text,actions,origin,page:pageContext()});history=store.current().messages;renderMessage(m);updateBubble();storageNotice();if(root.dataset.view==='history'&&historyMode==='list')renderSessions();}
const ready=store.ready.then(()=>{renderConversation();storageNotice();});
function guide(text){const t=text.toLowerCase().trim();if(/从哪里|如何开始|怎么开始|五个|全部案例|导览/.test(t))return{text:'可以按“岩屑 → 气测 → 荧光 → 钻时 → 报告”看，也可以直接选一例。每例都有背景、流程和交互演示。首页还收录其他12个阶段的新增案例。已载入的案例进入门户对应页，其余可直接打开独立演示。',actions:[...catalog.filter(c=>/^m[1-5]$/.test(c.id)).map(c=>({target:c.id})),{target:'home'}]};if(/真实.*荧光|真实.*配对|白光.*对照|方解石/.test(t))return{text:'这组真实照片展示同组方解石在可见光、短波UV和长波UV下的外观，用来理解矿物发光与油气解释的区别；不是含油岩屑训练数据。',actions:[{target:'fluorescence_reference'}]};if(/首页|回去|返回主页/.test(t))return{text:'点这里回到网站首页。',actions:[{target:'home'}]};if(/13|作业链|全部阶段/.test(t))return{text:'点这里查看原门户保留的作业链导航。',actions:[{target:'chain'}]};if(/录井阶段|进入录井/.test(t))return{text:'录井阶段包含五个必做子场景。',actions:[{target:'mudlogging'}]};if(/当前页|这个页面/.test(t)){const p=pageContext(),c=caseById(p.sceneId);return{text:c?c.intro:'当前是“'+p.title+'”。可以从首页选择案例，或通过13阶段导航浏览场景。',actions:c?[{target:c.id,tab:'bg'},{target:c.id,tab:'flow'},{target:c.id,tab:'demo'}]:[{target:'mudlogging'}]};}const c=catalog.find(c=>new RegExp('(?:^|[^a-z0-9])'+c.id+'(?:$|[^a-z0-9])','i').test(t)||c.terms.some(w=>t.includes(w)));if(c&&(!adapter||/打开|带我|进入|跳到|去看|看看/.test(t)||/^(m[1-5]|气测|岩屑|荧光|钻时|报告)$/.test(t))){let tab=/背景|概念/.test(t)?'bg':/流程|步骤/.test(t)?'flow':'demo';return{text:c.intro+'\n可以从这里进入对应内容。',actions:[{target:c.id,tab}]};}if(!adapter&&/模型|api|live2d|数字人|语音/.test(t))return{text:'角色状态：'+(g.S17Live2D?.state??'准备中')+'。本地导航与固定导学可用；开放式大模型问答可在右上角设置中连接火山方舟。浏览器朗读可手动开启。',actions:[]};return null;}
const tools=[{name:'navigate_page',description:'提供本站页面导航，仅使用允许的target，不执行JS或任意URL。',parameters:{type:'object',properties:{target:{type:'string',enum:['home','chain','mudlogging',...catalog.map(c=>c.id),'fluorescence_reference']},tab:{type:'string',enum:['bg','flow','demo']}},required:['target']}}];

